    /** Each keytool alias's chain as its keystore entry holds it, end entity first. */
    val jdkChains: Map<String, List<String>> = mapOf(
        "leaf-client-eku" to listOf("leaf-client-eku", "inter-ec", "root-ec"),
        "leaf-ed25519" to listOf("leaf-ed25519", "inter-ed25519", "root-ec"),
        "leaf-expired" to listOf("leaf-expired", "inter-ec", "root-ec"),
        "leaf-p256" to listOf("leaf-p256", "inter-ec", "root-ec"),
        "leaf-p384" to listOf("leaf-p384", "inter-ec", "root-ec"),
        "leaf-rsa" to listOf("leaf-rsa", "inter-rsa", "root-rsa"),
        "leaf-rsa-encipher" to listOf("leaf-rsa-encipher", "inter-rsa", "root-rsa"),
        "leaf-rsa-pkcs1-sha256" to listOf("leaf-rsa-pkcs1-sha256", "root-rsa"),
        "leaf-rsa-pkcs1-sha512" to listOf("leaf-rsa-pkcs1-sha512", "root-rsa"),
        "leaf-rsa-pss-sha384" to listOf("leaf-rsa-pss-sha384", "inter-rsa", "root-rsa"),
        "leaf-under-ee" to listOf("leaf-under-ee", "ee-issuer", "inter-ec", "root-ec"),
        "leaf-under-no-certsign" to listOf("leaf-under-no-certsign", "inter-no-certsign", "root-ec"),
    )

    fun jdkChain(alias: String): List<ByteArray> = jdkChains.getValue(alias).map { certificates.getValue(it) }

    val jdkRoots: Series<TrustAnchor> = s_[TrustAnchor.of(certificates.getValue("root-ec")), TrustAnchor.of(certificates.getValue("root-rsa"))]

    @Test fun ipAddressText() {
        assertContentEquals(byteArrayOf(127, 0, 0, 1), ipAddress("127.0.0.1"))
        assertContentEquals(ByteArray(15) + 1, ipAddress("::1"))
        assertContentEquals("20010db8000000000000ff0000428329".hexToByteArray(), ipAddress("2001:db8::ff00:42:8329"))
        assertContentEquals("00000000000000000000ffffc0000280".hexToByteArray(), ipAddress("::ffff:192.0.2.128"))
        for (text in listOf("localhost", "1.2.3", "1.2.3.04", "256.1.1.1", "1::2::3", "1:2:3:4:5:6:7:8:9", "12345::")) assertNull(ipAddress(text))
    }

    /** RFC 4514 strings as Python's cryptography renders them. */
    @Test fun rfc4514Names() {
        val chain = publicChains.getValue("storage.googleapis.com").map { X509Certificate(it) }
        assertEquals("CN=storage.googleapis.com", rfc4514(chain[0].subject))
        assertEquals("CN=WE2,O=Google Trust Services,C=US", rfc4514(chain[0].issuer))
        assertEquals("CN=GlobalSign Root CA,OU=Root CA,O=GlobalSign nv-sa,C=BE", rfc4514(chain[2].issuer))
    }
}
